sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here

	try {
        // Updated method name to match your POST Create HTTP Method
        var request = new sn_ws.RESTMessageV2('Scripted API Instance A to B', 'Post Method');

        var payLoad = {
            "opened_by": current.opened_by.toString(),
            "requestor": current.requestor.toString(),
            "type_of_asset": current.type_of_asset.toString(),
            "consumables": current.consumables.toString(),
            "company": current.company.toString(),
            "priority": current.priority.toString(),
            "short_description": current.short_description.toString(),
            "description": current.description.toString(),
            "correlation_id": current.getUniqueValue()
        };

        request.setRequestBody(JSON.stringify(payLoad));

        var response = request.execute();
        var httpStatus = response.getStatusCode();
        var responseBody = response.getBody();

        // /create strictly returns 201 on insert
        if (httpStatus == 201) {
            var parsedJson = JSON.parse(responseBody);
            var res = parsedJson.result;

            gs.info("[Scripted API POST] Success (" + res.status + "). Target SysID: " + res.sys_id);

            if (res && res.sys_id) {
                var gr = new GlideRecord(current.getTableName());
                if (gr.get(current.getUniqueValue())) {
                    gr.setValue('correlation_id', res.sys_id);
                    gr.setWorkflow(false);
                    gr.update();
                }
            }
        }
		else {
            gs.error("[Scripted API POST] Failed. Status: " + httpStatus + " Response: " + responseBody);
        }
    } 
	catch(ex) {
        gs.error("[Scripted API POST] Error: " + ex.getMessage());
    }

})(current, previous);
